// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // Fuzz parameter: an array of addresses for _tos. The distinguishing case is the empty array.
    // General rule: reference C reverts when _tos.length == 0 (due to require), so any call with an empty array cannot succeed;
    // the mutant that removed the require will succeed (return true) for empty arrays. We let the fuzzer supply the array.
    function testFuzz_property(address[] memory tos) public {
        // Keep domain wide: no assumptions. We'll observe whether transfer reverts for the empty-array case.
        bool ok;
        // Try the external call and record whether it reverted or not.
        try c.transfer(address(0x123), address(0x456), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property the reference satisfies: if tos.length == 0 then transfer must revert (ok == false).
        // The mutant that removed the require will make ok == true for some input (empty array), so this assertion will fail on the mutant for that input.
        if (tos.length == 0) {
            assertTrue(!ok);
        } else {
            // For non-empty, both versions should allow running; we cannot assert success universally because external calls inside loop may revert depending on callee.
            // So just assert true to avoid additional constraints.
            assertTrue(true);
        }
    }
}
